package com.acme.member.coupon;

import java.time.LocalDateTime;
import java.util.Objects;

public final class Coupon {
    public static final int MIN_DISCOUNT_PERCENT = 1;
    public static final int MAX_DISCOUNT_PERCENT = 100;

    private final String code;
    private final int discountPercent;
    private final LocalDateTime validFrom;
    private final LocalDateTime validUntil;
    private final boolean enabled;

    public Coupon(String code, int discountPercent, LocalDateTime validFrom, LocalDateTime validUntil, boolean enabled) {
        this.code = normalizeCode(code); // require non-blank
        if (discountPercent < 1 || >100) throw IAE
        Objects.requireNonNull(validFrom, validUntil)
        if (validUntil.isBefore(validFrom)) throw IAE? maybe allow
        ...
    }

    public static String normalizeCode(String raw) {
        if (raw == null) return null; // or ""?
        String trimmed = raw.trim();
        return trimmed.toUpperCase(Locale.ROOT);
    }

    public boolean isValidAt(LocalDateTime at) {
        return enabled && !at.isBefore(validFrom) && !at.isAfter(validUntil);
    }

    public long discountCents(long originalAmountCents) {
        if (originalAmountCents <= 0) throw IllegalArgumentException
        return (originalAmountCents * discountPercent + 50) / 100;
    }

    public long payableCents(long originalAmountCents) {
        long discount = discountCents(...); return original - discount;
    }

    getters...
}
