package com.acme.member.renewal;

import com.acme.member.coupon.Coupon;
import com.acme.member.coupon.CouponRepository;
import org.junit.jupiter.api.Test;

import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * 券目录与折扣计算（R1.S1、R1.S2、R1.S4）。
 *
 * <p>T1 只覆盖券模型、内置目录与整数分折扣算法；回调与试算在 T2/T3 扩展本类。
 */
class CouponRenewalTest {

    private static final LocalDateTime NOW = LocalDateTime.parse("2025-12-01T00:00:00");

    private final CouponRepository repository = new CouponRepository();

    @Test
    void builtInCatalogIsLookupable() {
        assertEquals(10, repository.findByCode("WELCOME10").orElseThrow().getDiscountPercent());
        assertEquals(15, repository.findByCode("RENEW15").orElseThrow().getDiscountPercent());
        assertEquals(20, repository.findByCode("RENEW20").orElseThrow().getDiscountPercent());
        assertTrue(repository.findByCode("EXPIRED10").isPresent());
        assertTrue(repository.findByCode("NO-SUCH-COUPON").isEmpty());
    }

    @Test
    void couponCodeIsTrimmedAndUppercased() {
        Optional<Coupon> found = repository.findByCode("  welcome10  ");

        assertTrue(found.isPresent());
        assertEquals("WELCOME10", found.orElseThrow().getCode());
    }

    @Test
    void blankOrMissingCouponCodeFindsNothing() {
        assertTrue(repository.findByCode(null).isEmpty());
        assertTrue(repository.findByCode("   ").isEmpty());
    }

    @Test
    void validityWindowIsInclusiveAndDependsOnInjectedTime() {
        Coupon welcome = repository.findByCode("WELCOME10").orElseThrow();
        Coupon expired = repository.findByCode("EXPIRED10").orElseThrow();

        assertTrue(welcome.isValidAt(NOW));
        assertFalse(expired.isValidAt(NOW));

        Coupon future = new Coupon("FUTURE10", 10,
                LocalDateTime.parse("2026-01-01T00:00:00"),
                LocalDateTime.parse("2026-12-31T23:59:59"),
                true);
        assertFalse(future.isValidAt(NOW));
        assertTrue(future.isValidAt(LocalDateTime.parse("2026-01-01T00:00:00")));
        assertTrue(future.isValidAt(LocalDateTime.parse("2026-12-31T23:59:59")));
        assertFalse(future.isValidAt(LocalDateTime.parse("2027-01-01T00:00:00")));
    }

    @Test
    void disabledCouponIsInvalidEvenInsideWindow() {
        Coupon disabled = new Coupon("DISABLED10", 10,
                LocalDateTime.parse("2024-01-01T00:00:00"),
                LocalDateTime.parse("2026-12-31T23:59:59"),
                false);

        assertFalse(disabled.isValidAt(NOW));
    }

    @Test
    void discountUsesIntegerHalfUpRounding() {
        Coupon welcome = repository.findByCode("WELCOME10").orElseThrow();
        Coupon renew15 = repository.findByCode("RENEW15").orElseThrow();

        assertEquals(990, welcome.discountCents(9900));
        assertEquals(8910, welcome.payableCents(9900));

        assertEquals(1500, renew15.discountCents(9999));
        assertEquals(8499, renew15.payableCents(9999));

        // 10 * 15% = 1.5 分，HALF_UP 应进位到 2。
        assertEquals(2, renew15.discountCents(10));
        assertEquals(8, renew15.payableCents(10));
    }

    @Test
    void customCatalogCanReplaceBuiltInCoupons() {
        Coupon vip = new Coupon("VIP25", 25,
                LocalDateTime.parse("2025-01-01T00:00:00"),
                LocalDateTime.parse("2025-12-31T23:59:59"),
                true);
        CouponRepository custom = new CouponRepository(List.of(vip));

        assertEquals(25, custom.findByCode(" vip25 ").orElseThrow().getDiscountPercent());
        assertTrue(custom.findByCode("WELCOME10").isEmpty());
    }

    @Test
    void invalidAmountOrPercentIsRejected() {
        Coupon welcome = repository.findByCode("WELCOME10").orElseThrow();

        assertThrows(IllegalArgumentException.class, () -> welcome.discountCents(0));
        assertThrows(IllegalArgumentException.class, () -> welcome.discountCents(-1));
        assertThrows(IllegalArgumentException.class, () -> new Coupon("BAD", 0,
                NOW, NOW.plusDays(1), true));
        assertThrows(IllegalArgumentException.class, () -> new Coupon("BAD", 101,
                NOW, NOW.plusDays(1), true));
    }
}

